"""Applications of Ceva and Van Aubel, printed page 221."""
from math import sqrt,dist
from midpoint_lessons import make,edges,views,coordinates,foot,fit_visible
from fractions import Fraction as F


def chapter8(n,statement,result,hint,steps,frames,practice):
    item=make(n,statement,result,hint,steps,frames,practice)
    item.update(printedPages=[221],pdfPages=[222])
    return item


def section():
    c,a,b=(0,0),(6,0),(0,4)
    h=foot(c,a,b);d=(-4,0);e=(-4,4);f=(0,-6);k=(6,-6)
    common=F(12,5);x=(common,0);y=(0,common)
    # Intersect AE (slope -2/5) with CH (slope 3/2).
    o=(F(24,19),F(36,19))
    p=dict(A=a,B=b,C=c,H=h,D=d,E=e,F=f,K=k,X=x,Y=y,O=o)
    base=edges('ABC')+edges('ACFK')+edges('BCDE')+[('C','H'),('B','K'),('A','E')]
    z895=chapter8(895,'На катетах AC и BC прямоугольного ABC снаружи построены квадраты ACFK и BCDE. H — основание высоты из C к AB. Докажи, что CH, BK и AE проходят через одну точку.',
        'Пусть X=BK∩AC, Y=AE∩BC. Отношения AH/HB, BY/YC и CX/XA имеют произведение 1. Точки H,Y,X внутренние, значит применима обратная теорема Чевы.',
        'Подбери три внутренние точки для теоремы Чевы. В двух малых треугольниках используй параллельные стороны квадратов.',
        [('Как далеко X и Y от C?', 'Пусть AC=a, BC=b. Считай C=(0,0), A=(a,0), B=(0,b). Тогда K=(a,−a), E=(−b,b). На прямой BK точка с нулевой второй координатой имеет первую ab/(a+b). На AE точка с нулевой первой координатой имеет вторую ab/(a+b). Поэтому CX=CY=ab/(a+b).',
          'Например, при движении от B к K ордината падает от b до −a. Чтобы стать нулевой, нужно пройти долю b/(a+b) от всего отрезка.'),
         ('Каковы три отношения для Чевы?', 'Вычитание из катетов даёт BY=b²/(a+b), XA=a²/(a+b). Поэтому BY/YC=b/a и CX/XA=b/a. Высота к гипотенузе даёт AH/HB=a²/b², поскольку AH=a²/AB, HB=b²/AB по подобию прямоугольных треугольников.',
          'Проекция катета на гипотенузу равна квадрату катета, делённому на гипотенузу.'),
         ('Почему получится конечная общая точка?', 'Перемножь (a²/b²)·(b/a)·(b/a): результат 1. Все три точки H,Y,X лежат внутри сторон. По обратной теореме Чевы CH, AY и BX пересекаются в одной внутренней точке, а AY лежит на AE и BX на BK.',
          'Для внутренних точек три чевианы с единичным произведением отношений пересекаются.')],
        views(p,base,((),()),((),('BCX','AKX')),((),('AHC','BHC')),((),('ABC',))),
        (1,'При AC=6 и BC=4 найди CX, запиши десятичную дробь.', ['2,4','2.4'],'Раздели 6·4 на 6+4.'))
    a,b,c=(0,0),(8,0),(2,6);x=(2,0);y=(4,4);z=(.8,2.4);o=(2,2)
    p=dict(A=a,B=b,C=c,X=x,Y=y,Z=z,O=o);base=edges('ABC')+[('C','X'),('A','Y'),('B','Z')]
    z896=chapter8(896,'На сторонах AB, BC, CA треугольника ABC выбраны X,Y,Z. Отрезки CX, AY, BZ пересеклись в O. Докажи равенство Ван-Обеля CO/OX=CY/YB+CZ/ZA.',
        'Если площади OBC, OCA, OAB обозначить u,v,w, то обе части равны (u+v)/w.',
        'Раздели исходный треугольник на три части с общей вершиной O. Затем сравни высоты к основаниям, лежащим на одной прямой.',
        [('Как выразить CY/YB и CZ/ZA?', 'Пусть u=S(OBC), v=S(OCA), w=S(OAB). У OCA и OBA общая основа OA. Отношение высот от C и B к OA равно CY/YB, так как A,O,Y коллинеарны. Поэтому CY/YB=v/w. Сравнение OBC и OBA по основанию OB даёт CZ/ZA=u/w.',
          'Расстояния от двух точек одной прямой до пересекающей её прямой пропорциональны расстояниям до точки пересечения.'),
         ('Какую долю площади занимает OAB?', 'При общем основании AB площади OAB и CAB относятся как высоты из O и C. Точки X,O,C на одной прямой, а X находится на AB. Отсюда w/(u+v+w)=OX/CX.',
          'O внутри треугольника, поэтому сумма трёх малых площадей равна всей площади.'),
         ('Как получить именно CO/OX?', 'Обрати предыдущее равенство и вычти 1. Слева (u+v+w)/w−1=(u+v)/w. Справа CX/OX−1=CO/OX. Сумма v/w+u/w из первого шага даёт формулу.',
          'CX=CO+OX, поскольку O находится между C и X.')],
        views(p,base,((),()),((),('OBC','OCA','OAB')),((),('OAB','CAB')),((),('OBC','OCA'))),
        (3,'Если CY/YB=2 и CZ/ZA=3, каким будет CO/OX?', ['5'],'Сложи два отношения.'))
    a,b,c=(0,0),(8,0),(0,6);o=(2,2);d=(F(24,7),F(24,7));y=foot(o,b,c);z=(0,2);x=(2,0)
    p=dict(A=a,B=b,C=c,O=o,D=d,X=x,Y=y,Z=z);base=edges('ABC')+[('A','D')]
    z897=chapter8(897,'Пусть O — точка пересечения биссектрис ABC, а AD — биссектриса из A. Докажи, что AO/OD=(AB+AC)/BC. Как перенести вывод на остальные вершины?',
        'У треугольников OAB, OAC и OBC высоты из O к соответствующим сторонам равны радиусу вписанной окружности. Это даёт AO/OD=(AB+AC)/BC.',
        'Свяжи положение O на AD с долей площади OBC во всём треугольнике ABC.',
        [('Как связаны площади трёх частей?', 'Точка O равноудалена от трёх сторон. Пусть r — общее расстояние. Тогда S(OAB)=r·AB/2, S(OAC)=r·AC/2, S(OBC)=r·BC/2.',
          'Для точки биссектрисы расстояния до сторон угла одинаковы.'),
         ('Как связать OD/AD с площадями?', 'Сравни OBC и ABC при основании BC. Отношение высот из O и A равно OD/AD, поскольку A,O,D коллинеарны и D лежит на BC. Значит AD/OD=S(ABC)/S(OBC).',
          'Перпендикулярные расстояния точек одного луча до прямой через начало луча пропорциональны расстояниям до начала.'),
         ('Что изменится, если брать длину от самой вершины?', 'Вычти 1 из обеих частей: AO/OD=[S(OAB)+S(OAC)]/S(OBC). Подставь три выражения из первого шага и сократи r/2. При замене букв по кругу аналогично получишь формулы для биссектрис из B и C.',
          'AO=AD−OD; три треугольника с общей вершиной O заполняют исходный ABC.')],
        views(p,base,((),()),([('O','X'),('O','Y'),('O','Z')],('OAB','OAC','OBC')),((),('OBC','ABC')),((),('OAB','OAC'))),
        (3,'При AB=8, AC=6 и BC=10 найди AO/OD десятичной дробью.', ['1,4','1.4'],'Раздели сумму двух прилежащих сторон на противоположную.'))
    p=dict(A=a,B=b,C=c,O=o,X=x,Y=y,Z=z);base=edges('ABC')
    z898=chapter8(898,'Вписанная окружность ABC касается AB в X, BC в Y и CA в Z. Докажи, что CX, AY и BZ пересекаются в одной точке — точке Жергонна.',
        'Равные касательные от каждой вершины сводят произведение отношений Чевы к (u/v)·(v/w)·(w/u)=1.',
        'Подпиши одним обозначением обе касательные, проведённые из одной вершины.',
        [('Какие отрезки у каждой вершины равны?', 'Из A получаем AX=AZ=u, из B — BX=BY=v, из C — CY=CZ=w. Все шесть отрезков положительны, поскольку точки касания находятся внутри сторон.',
          'Два отрезка касательных, проведённых из одной внешней точки к окружности, равны.'),
         ('Какие отношения подходят для Чевы?', 'На AB получаем AX/XB=u/v. На BC имеем BY/YC=v/w, а на CA — CZ/ZA=w/u. Важно выбрать один порядок обхода треугольника.',
          'В циклическом произведении каждое обозначение один раз оказывается в числителе и один раз в знаменателе.'),
         ('Почему в итоге действительно есть общая точка?', 'Произведение равно 1. Поскольку X,Y,Z внутренние, обратная теорема Чевы утверждает, что CX, AY, BZ пересекаются внутри треугольника.',
          'Внутреннее положение точек исключает параллельность чевиан.')],
        views(p,base,((),()),([('O','X'),('O','Y'),('O','Z')],()),((),()),([('C','X'),('A','Y'),('B','Z')],())),
        (2,'Если AX=2, BX=6 и CY=4, чему равно отношение BY/YC?', ['1,5','1.5'],'BY=BX, затем раздели 6 на 4.'))
    x=(6,0);y=coordinates(b,c,F(2,5));z=(0,4);p=dict(A=a,B=b,C=c,X=x,Y=y,Z=z,U=(12,0),V=(0,12),I=(12,12));base=edges('ABC')
    z899=chapter8(899,'Вневписанная окружность, противолежащая A, касается BC в Y. Аналогично окружности против B и C касаются самих сторон CA и AB в Z и X. Почему AY, BZ, CX проходят через общую точку Нагеля?',
        'При полупериметре s и сторонах a=BC, b=CA, c=AB у трёх точек касания длины выражаются через s−a, s−b, s−c. В произведении Чевы они сокращаются.',
        'Сначала найди BY и CY. Отметь, где та же окружность касается продолжений AB и AC.',
        [('Как вычислить BY у первой окружности?', 'Обозначь через U и V касания продолжений AB за B и AC за C. Имеем BU=BY и CV=CY. Из AU=AV следует c+BY=b+CY. Сложи с равенством BY+CY=a и получи BY=(a+b−c)/2=s−c. Значит CY=s−b.',
          'Точки Y на BC, U и V на продолжениях относятся к одной вневписанной окружности.'),
         ('Какие длины возникают на остальных сторонах?', 'Поменяв вершины циклически, получаем CZ=s−a, ZA=s−c, AX=s−b, XB=s−a. Таким образом на каждой стороне записаны длины двух касательных, нужных для отношений.',
          'При циклической замене букв меняются одновременно вершины, их противоположные стороны и вневписанные окружности.'),
         ('Как завершить доказательство?', 'Перемножь (s−b)/(s−a), (s−c)/(s−b), (s−a)/(s−c). Получишь 1. Все контактные точки расположены внутри соответствующих сторон, поэтому по Чеве три чевианы имеют одну общую точку.',
          'В невырожденном треугольнике s больше каждой из трёх сторон.')],
        views(p,base,((),()),([('B','U'),('C','V')],()),((),()),([('C','X'),('A','Y'),('B','Z')],())),
        (1,'Если a=10, b=6, c=8, чему равно BY?', ['4'],'Сначала найди s=(10+6+8)/2, затем s−c.'))
    z899['model']['views']['step-1']['circles']=[dict(center='I__v1',through='Y__v1')]
    # The incircle in the Gergonne configuration is part of every frame.
    for i,v in enumerate(z898['model']['views'].values()):v['circles']=[dict(center=f'O__v{i}',through=f'X__v{i}')]
    for obj in [z895,z896,z897,z898,z899]:
        for i,v in enumerate(obj['model']['views'].values()):
            visible={k for row in v['segments']+v.get('polygons',[]) for k in row}
            if obj is z895 and i>0:visible.update(f'{k}__v{i}' for k in 'XY')
            if obj is z895 and i==3:visible.add(f'O__v{i}')
            if obj is z898:visible.update(f'{k}__v{i}' for k in 'OXYZ')
            if obj is z899:visible.update(f'{k}__v{i}' for k in 'XYZ')
            v['points']=[k for k in v['points'] if k in visible]
    fit_visible(z899)
    return [z895,z896,z897,z898,z899]
